import socket
import subprocess
import time
from moler.device import DeviceFactory
from taf.rfrl.utilities.tl_config import load_moler_configuration_from_tl


def get_vm_fqdn():
    """
    Returns FQDN of the machine. eg: 7-7-tspy047.sc5g.krk-lab.nsn-rdnet.net
    """
    result = subprocess.run(['host', socket.gethostname()],
                            capture_output=True, text=True)
    output = result.stdout.strip()
    fqdn = output.split(' ')[0]
    return fqdn


def get_vm_ip_address():
    """
    Returns IP address of the machine.
    """
    result = subprocess.run(['hostname', '-I'], capture_output=True, text=True)
    ip_address = result.stdout.strip().split()[0]  # Get the first IP address
    return ip_address


def get_vm_hostname():
    """
    Returns hostname of the machine.
    """
    result = subprocess.run(['hostname'], capture_output=True, text=True)
    hostname = result.stdout.strip()
    return hostname


def get_vm_vnc_password(file_path='/etc/ute/vncpasswd'):
    """
    Returns VNC password of the machine.
    """
    result = subprocess.run(['sudo', 'cat', file_path], capture_output=True, text=True)
    return result.stdout.strip()


@load_moler_configuration_from_tl()
def get_test_pc_hostname(device_name='TEST_PC'):
    """
    Returns the hostname of the test PC.
    """
    test_pc = DeviceFactory.get_device(name=device_name)
    hostname = test_pc.get_cmd(cmd_name='hostname')()['hostname']
    return hostname


@load_moler_configuration_from_tl()
def dump_current_disk_space_usage_on_ute_vm():
    """
    Dumps current disk space usage on UTE VM.
    """
    unix_local = DeviceFactory.get_device(name='UnixLocal')
    unix_local.get_cmd(cmd_name="df")(timeout=60)
    time.sleep(0.5)
    unix_local.get_cmd(cmd_name="du", cmd_params={"options": '-Sh /home/ute | sort -rh | head -10'})(timeout=5 * 60)
    time.sleep(0.5)
    unix_local.get_cmd(cmd_name="du", cmd_params={"options": '-Sh /tmp | sort -rh | head -10'})(timeout=5 * 60)
